mapper.update:
update wx_click_log
open_id = #{openId}, create_time = #{createTime}, update_time = #{updateTime},
where id = #{id}

mapper.select:
SELECT COALESCE(pv, 0) as pv, COALESCE(uv, 0) as uv, COALESCE(time, #{time}) as time, 'app' as name FROM ( SELECT COUNT(*) as pv, COUNT(DISTINCT open_id) as uv, DATE_FORMAT(create_time,'%Y-%m-%d') as time FROM wx_click_log
and DATE_FORMAT(create_time,'%Y-%m-%d') = #{time}
GROUP BY time ) AS t RIGHT JOIN (SELECT #{time} AS date) AS r ON t.time = r.date;

